package com.simibubi.create.test;

import com.mojang.blaze3d.platform.InputConstants;
import com.simibubi.create.*;
import com.simibubi.create.content.equipment.symmetryWand.*;
import com.simibubi.create.content.equipment.symmetryWand.mirror.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.*;
import java.util.function.Predicate;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;

/** Opt-in physical SDL input, real finite native stock and Vulkan source model/screen proof. Runtime UNRUN. */
final class SymmetryWandRenderingTest {
    private static final BlockPos CENTER=new BlockPos(60012,5,12),SOURCE=CENTER.west(2),TARGET=CENTER.east(2);
    static void run(ClientGameTestContext c,TestSingleplayerContext w){
        var camera=c.computeOnClient(client->client.options.getCameraType());boolean hidden=c.computeOnClient(client->client.gui.hud.isHidden());
        try{c.runOnClient(client->{client.options.setCameraType(CameraType.FIRST_PERSON);if(client.gui.hud.isHidden())client.gui.hud.toggle();});scene(c,w);SymmetryWandCompositionRenderingTest.run(c,w);}finally{c.getInput().releaseKey(InputConstants.KEY_LSHIFT);c.getInput().releaseKey(options->options.keyUse);c.getInput().releaseKey(options->options.keyAttack);c.getInput().releaseKey(options->options.keySwapOffhand);c.runOnClient(client->{client.options.setCameraType(camera);if(client.gui.hud.isHidden()!=hidden)client.gui.hud.toggle();});}
    }
    private static void scene(ClientGameTestContext c,TestSingleplayerContext w){
        var server=w.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 60008.5 10 12.5");c.waitFor(client->client.level.isLoaded(CENTER)&&client.level.isLoaded(TARGET),450);NativeScreenshotReadiness.beforeFloor(c, w, new BlockPos(60004, 4, 4), new BlockPos(60020, 4, 20), CENTER, SOURCE, TARGET);
        server.runCommand("fill 60004 4 4 60020 4 20 minecraft:smooth_quartz");
        NativeScreenshotReadiness.afterFloor(c, w, new BlockPos(60004, 4, 4), new BlockPos(60020, 4, 20));server.runCommand("fill 60004 5 4 60020 8 20 minecraft:air");server.runCommand("clear @p");server.runCommand("gamemode survival @p");server.runCommand("tp @p 60008.5 5 12.5");
        c.waitFor(client->client.player.onGround()&&!client.player.isSpectator()&&client.gameRenderer.mainCamera().position().distanceToSqr(client.player.getEyePosition())<1,250);select(c,w,InputConstants.KEY_1,0);
        var serverOwner=new AtomicReference<ItemStack>();server.runOnServer(ignored->{var player=actual(w.getConnection().getServerLevel());var originalWand=new ItemStack(AllItems.WAND_OF_SYMMETRY);serverOwner.set(originalWand);slot(player,0,originalWand);slot(player,1,new ItemStack(Items.COBBLESTONE,8));slot(player,2,new ItemStack(Items.DIAMOND_PICKAXE));});c.waitFor(client->client.player.getMainHandItem().is(AllItems.WAND_OF_SYMMETRY)&&client.player.getInventory().getItem(1).getCount()==8,250);
        use(c,CENTER.below(),Vec3.atCenterOf(CENTER.below()).add(0,.499,0));await(c,w,level->{var wand=actual(level).getInventory().getItem(0);var mirror=SymmetryWandItem.getMirror(wand);return SymmetryWandItem.isEnabled(wand)&&mirror instanceof PlaneMirror&&mirror.getPosition().equals(Vec3.atLowerCornerOf(CENTER))&&mirror.getOrientationIndex()==1;},220,"Physical native wand input did not place the source YZ mirror");
        c.waitFor(client->SymmetryWandClient.latest().markers().size()==1&&!SymmetryWandClient.latest().markers().getFirst().model().isEmpty(),220);screenshot(c,"create-vulkan-symmetry-source-plane-marker-and-animated-paid-native-wand",false);
        c.getInput().holdKey(InputConstants.KEY_LSHIFT);c.waitTicks(8);c.getInput().pressKey(options->options.keyUse);c.waitFor(client->client.gui.screen() instanceof SymmetryWandScreen,220);c.getInput().releaseKey(InputConstants.KEY_LSHIFT);
        clickWidget(c,0);c.waitFor(client->client.gui.screen() instanceof SymmetryWandScreen screen&&screen.settings() instanceof CrossPlaneMirror,220);screenshot(c,"create-vulkan-symmetry-native-cross-plane-configuration-picture-in-picture-and-source-wand",true);
        clickWidget(c,2);c.waitFor(client->client.gui.screen()==null,220);await(c,w,level->SymmetryWandItem.getMirror(actual(level).getInventory().getItem(0)) instanceof CrossPlaneMirror,220,"Physical confirmation did not reach guarded actual server wand session");
        verifyKind(c,w,serverOwner.get(),SymmetryMirror.CROSS_PLANE,56,3);screenshot(c,"create-vulkan-symmetry-typed-native-cross-y-owned-server-client-and-56-face-marker",56,0);
        openWand(c);clickWidget(c,0);c.waitFor(client->client.gui.screen() instanceof SymmetryWandScreen screen&&screen.settings() instanceof TriplePlaneMirror,220);screenshot(c,"create-vulkan-symmetry-typed-triple-dialog-68-face-preview-over-cross-56-world",56,68);clickWidget(c,2);c.waitFor(client->client.gui.screen()==null,220);
        verifyKind(c,w,serverOwner.get(),SymmetryMirror.TRIPLE_PLANE,68,7);screenshot(c,"create-vulkan-symmetry-normal-native-cross-to-triple-sync-and-68-face-marker",68,0);
        openWand(c);clickWidget(c,0);c.waitFor(client->client.gui.screen() instanceof SymmetryWandScreen screen&&screen.settings() instanceof PlaneMirror,220);clickWidget(c,0);c.waitFor(client->client.gui.screen() instanceof SymmetryWandScreen screen&&screen.settings() instanceof CrossPlaneMirror,220);screenshot(c,"create-vulkan-symmetry-typed-cross-dialog-56-face-preview-over-triple-68-world",68,56);clickWidget(c,2);c.waitFor(client->client.gui.screen()==null,220);
        verifyKind(c,w,serverOwner.get(),SymmetryMirror.CROSS_PLANE,56,3);screenshot(c,"create-vulkan-symmetry-normal-native-triple-back-to-cross-sync-and-56-face-marker",56,0);
        select(c,w,InputConstants.KEY_2,1);use(c,SOURCE.below(),Vec3.atCenterOf(SOURCE.below()).add(0,.499,0));await(c,w,level->level.getBlockState(SOURCE).is(Blocks.COBBLESTONE)&&level.getBlockState(TARGET).is(Blocks.COBBLESTONE)&&actual(level).getInventory().countItem(Items.COBBLESTONE)==6,220,"Actual native source and mirrored placement did not consume exactly two of original eight materials");
        c.waitFor(client->client.level.getBlockState(TARGET).is(Blocks.COBBLESTONE),220);look(c,Vec3.atCenterOf(CENTER).add(0,1,0));c.takeScreenshot("create-vulkan-symmetry-two-real-physical-placements-paid-once-and-native-cross-marker");
        select(c,w,InputConstants.KEY_3,2);look(c,Vec3.atCenterOf(SOURCE));c.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(SOURCE),200);c.getInput().holdKey(options->options.keyAttack);
        try{await(c,w,level->level.getBlockState(SOURCE).isAir()&&level.getBlockState(TARGET).isAir(),260,"Physical native mining did not break original and reflected targets");}finally{c.getInput().releaseKey(options->options.keyAttack);}
        await(c,w,level->{int loose=level.getEntitiesOfClass(ItemEntity.class,new AABB(CENTER).inflate(10)).stream().filter(entity->entity.getItem().is(Items.COBBLESTONE)).mapToInt(entity->entity.getItem().getCount()).sum();return actual(level).getInventory().countItem(Items.COBBLESTONE)+loose==8&&actual(level).getMainHandItem().getDamageValue()==2;},220,"Real native mining loot/tool charge failed to conserve eight original paid materials and two actual uses");
        select(c,w,InputConstants.KEY_1,0);var before=c.computeOnClient(client->SymmetryWandItemRenderer.INSTANCE.extractArgument(client.player.getMainHandItem()).draws.getFirst().quads());var reload=c.computeOnClient(Minecraft::reloadResourcePacks);c.waitFor(client->reload.isDone()&&client.gui.overlay()==null,650);reload.join();c.runOnClient(client->{if(SymmetryWandItemRenderer.INSTANCE.extractArgument(client.player.getMainHandItem()).draws.getFirst().quads()==before)throw new AssertionError("Native source wand resource reload retained stale baked geometry");});screenshot(c,"create-vulkan-symmetry-source-models-and-live-mirror-after-native-resource-reload",false);server.runCommand("gamemode spectator @p");
    }
    private static void openWand(ClientGameTestContext c){look(c,Vec3.atCenterOf(CENTER.below()).add(0,.499,0));c.getInput().holdKey(InputConstants.KEY_LSHIFT);c.waitTicks(8);c.getInput().pressKey(options->options.keyUse);c.waitFor(client->client.gui.screen() instanceof SymmetryWandScreen,220);c.getInput().releaseKey(InputConstants.KEY_LSHIFT);}
    private static void verifyKind(ClientGameTestContext c,TestSingleplayerContext w,ItemStack exactServerOwner,String expected,int markerFaces,int reflections){
        await(c,w,level->{var player=actual(level);var stack=player.getInventory().getItem(0);var data=stack.get(AllDataComponents.SYMMETRY_WAND);var mirror=SymmetryWandItem.getMirror(stack);boolean concrete=expected.equals(SymmetryMirror.TRIPLE_PLANE)?mirror.getClass()==TriplePlaneMirror.class:mirror.getClass()==CrossPlaneMirror.class;var actualTargets=mirror.process(CENTER.offset(3,0,1),Blocks.COBBLESTONE.defaultBlockState()).keySet();var manual=new HashSet<BlockPos>(List.of(CENTER.offset(-3,0,1),CENTER.offset(3,0,-1),CENTER.offset(-3,0,-1)));if(reflections==7)manual.addAll(List.of(CENTER.offset(-1,0,-3),CENTER.offset(-1,0,3),CENTER.offset(1,0,-3),CENTER.offset(1,0,3)));return stack==exactServerOwner&&data!=null&&data.type().equals(expected)&&data.orientationIndex()==0&&data.position().equals(Vec3.atLowerCornerOf(CENTER))&&data.enable()&&SymmetryWandItem.isEnabled(stack)&&concrete&&actualTargets.equals(manual)&&actualTargets.size()==reflections;},220,"Actual server owner/type/center/index/source geometry did not become "+expected);
        c.waitFor(client->{var stack=client.player.getInventory().getItem(0);var data=stack.get(AllDataComponents.SYMMETRY_WAND);var raw=SymmetryWandItem.getMirror(stack);boolean concrete=expected.equals(SymmetryMirror.TRIPLE_PLANE)?raw.getClass()==TriplePlaneMirror.class:raw.getClass()==CrossPlaneMirror.class;var markers=SymmetryWandClient.latest().markers();return data!=null&&data.type().equals(expected)&&data.orientationIndex()==0&&data.position().equals(Vec3.atLowerCornerOf(CENTER))&&data.enable()&&concrete&&markers.size()==1&&markers.getFirst().position().equals(Vec3.atLowerCornerOf(CENTER))&&markers.getFirst().model().mesh!=null&&markers.getFirst().model().mesh.size()==markerFaces;},250);
    }
    private static void screenshot(ClientGameTestContext c,String label,int worldFaces,int portraitFaces){c.waitFor(client->client.gui.overlay()==null,250);c.runOnClient(client->{client.gui.hud.getChat().clearMessages(false);SymmetryWandNativeProbe.begin(label,worldFaces,portraitFaces);});try{c.takeScreenshot(label);}finally{c.runOnClient(client->SymmetryWandNativeProbe.end(portraitFaces>0));}}
    private static void screenshot(ClientGameTestContext c,String label,boolean preview){c.waitFor(client->client.gui.overlay()==null,250);c.runOnClient(client->{client.gui.hud.getChat().clearMessages(false);SymmetryWandNativeProbe.begin(label);});try{c.takeScreenshot(label);}finally{c.runOnClient(client->SymmetryWandNativeProbe.end(preview));}}
    private static void clickWidget(ClientGameTestContext c,int index){var point=c.computeOnClient(client->{var screen=client.gui.screen();var button=screen.children().stream().filter(AbstractWidget.class::isInstance).map(AbstractWidget.class::cast).toList().get(index);var window=client.getWindow();return new Vec2((button.getX()+button.getWidth()/2f)*window.getScreenWidth()/window.getGuiScaledWidth(),(button.getY()+button.getHeight()/2f)*window.getScreenHeight()/window.getGuiScaledHeight());});c.getInput().setCursorPos(point.x,point.y);c.waitTicks(2);c.getInput().pressMouse(InputConstants.MOUSE_BUTTON_LEFT);}
    private static void use(ClientGameTestContext c,BlockPos pos,Vec3 point){look(c,point);c.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(pos)&&hit.getDirection()==Direction.UP,220);c.getInput().pressKey(options->options.keyUse);}
    private static void look(ClientGameTestContext c,Vec3 point){c.runOnClient(client->{var diff=point.subtract(client.player.getEyePosition());client.player.setYRot((float)Math.toDegrees(Math.atan2(-diff.x,diff.z)));client.player.setXRot((float)-Math.toDegrees(Math.atan2(diff.y,Math.sqrt(diff.x*diff.x+diff.z*diff.z))));});c.waitTicks(4);}
    private static void select(ClientGameTestContext c,TestSingleplayerContext w,int key,int slot){c.getInput().pressKey(key);c.waitFor(client->client.player.getInventory().getSelectedSlot()==slot,200);await(c,w,level->actual(level).getInventory().getSelectedSlot()==slot,200,"Native selected slot was not acknowledged");}
    private static void slot(ServerPlayer player,int slot,ItemStack stack){player.getInventory().setItem(slot,stack);player.connection.send(player.getInventory().createInventoryUpdatePacket(slot));}
    private static ServerPlayer actual(ServerLevel level){return level.getServer().getPlayerList().getPlayers().getFirst();}
    private static void await(ClientGameTestContext c,TestSingleplayerContext w,Predicate<ServerLevel> predicate,int ticks,String failure){var accepted=new AtomicBoolean();for(int tick=0;tick<ticks;tick++){w.getServer().runOnServer(ignored->accepted.set(predicate.test(w.getConnection().getServerLevel())));if(accepted.get())return;c.waitTicks(1);}throw new AssertionError(failure);}
    private SymmetryWandRenderingTest(){}
}
